// no-deps-policy command fixtures: every table line is a literal Bash
// payload the policy must judge.

export const DENY: string[] = [
  "pip install x",
  "pip3 install x",
  "python3 -m pip install x",
  "uv add x",
  "uv pip install x",
  "uv tool install x",
  "uv self update",
  "pipx install x",
  "poetry add x",
  "poetry self update",
  "npm install",
  "npm i",
  "npm ci",
  "npm uninstall x",
  "yarn add x",
  "pnpm add x",
  "pnpm up",
  "bun add x",
  "bun i",
  "cargo add x",
  "rustup update",
  "composer require x",
  "composer global update",
  "gem install x",
  "go get x",
  "go mod tidy",
  "swift package resolve",
  "brew install x",
  "brew services start",
  "npx create-thing",
  "bunx create-thing",
  "deno add x",
  "cd /x && npm install",
  "FOO=1 pip install x",
  "NPM i",
  "Pip3 install x",
  "Cargo ADD serde",
  "npx",
  "bunx",
  // npx-equivalents and global installs found in review
  "uvx ruff",
  "uvx ruff@latest check .",
  "yarn global add x",
  "yarn global remove x",
  "npm exec --yes create-vite@latest",
  "npm create vite@latest",
  "npm init vite",
  "python3.12 -m pip install x",
  // surface from the machine inventory (tmp/pm-inventory.md)
  "pnpx create-thing",
  "bun x cowsay",
  "deno x cowsay",
  "uv tool run ruff",
  "pipx run ruff",
  "pnpm dlx vite",
  "pnpm exec vitest",
  "yarnpkg add x",
  "bundler install",
  "pipx install-all",
  "npm install-ci-test",
  "pnpm self-update",
  "brew update",
  "brew bundle",
  "nix run nixpkgs#hello",
  "nix shell nixpkgs#hello",
  "cargo binstall ripgrep",
  "cargo fetch",
  "go run example.com/pkg@latest",
  "go run golang.org/x/tools/cmd/goimports@latest",
  "deno run https://example.com/x.ts",
  "deno run npm:cowsay",
  "deno run HTTPS://example.com/x.ts",
  "deno run NPM:cowsay",
  "deno run jsr:@std/path",
  // URL/module-ref boundaries: any absolute URL scheme denies, and the
  // versioned module-suffix form denies
  "go run golang.org/x/y@v1.2.3",
  "deno run data:text/javascript,alert(1)",
  "pnpm with 9",
  "uv run x.py",
  "uv python install 3.13",
  "swift package add-dependency x",
  "rustup target add wasm32-unknown-unknown",
  "poetry source add x",
  "python3.15 -m pip install x",
  "gem update x",
];

export const ALLOW: string[] = [
  "npm info x",
  "npm run build",
  "npm test",
  "pip --version",
  "python3 app.py",
  "cargo build",
  "cargo test",
  "go build ./...",
  "go mod verify",
  "brew list",
  "brew info x",
  "deno run x",
  "bun test",
  "cat package.json",
  "echo 'npm install x'",
  "man npm install",
  "NPM info x",
  "uv tool list",
  "python3.13 --version",
  // local runners stay allowed; only fetch forms deny
  "yarn set version 4",
  "poetry run pytest",
  "bundle exec rspec",
  "composer exec vendor/bin/x",
  "cargo run",
  "go run .",
  "go run main.go",
  "go run ./cmd/tool",
  "deno eval 1+1",
  "pipx exec app",
  "pnpm list",
  // fetch-form boundaries stay allowed: host "." is not a module host, and a
  // scheme-less single word is not a URL (URL.canParse false)
  "go run ./cmd/tool@v1",
  "deno run main.go",
];
